from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from silk.models import SQLQuery

class SilkRequestSQLTracesView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, trace_id):
        # Restrict query inspection to traces owned by the authenticated caller
        queries = SQLQuery.objects.filter(
            request_id=trace_id,
            request__user_id=request.user.id
        ).values(
            "query", "time_taken", "traceback"
        )
        if not queries:
            return Response({"error": "No SQL logs found or access denied"}, status=status.HTTP_404_NOT_FOUND)

        return Response({"sql_queries": list(queries)}, status=status.HTTP_200_OK)
